def build_oracle(qc: QuantumCircuit, problem_qubits: list[int],
                 ancilla_qubits: list[int]) -> None:
    # 4 edges of the graph: (0,2), (1,2), (1,3), (2,3)
    edges = [(0, 2), (1, 2), (1, 3), (2, 3)]

    # Precompute all 4-bit patterns (a0,a1,b0,b1) where the decoded colours differ.
    # Vertex code → colour: colour = (b0 + 2*b1) mod 3  (valid codes 0,1,2; 11 → 0)
    patterns_diff = []
    for a0 in (0, 1):
        for a1 in (0, 1):
            for b0 in (0, 1):
                for b1 in (0, 1):
                    colour_u = (a0 + 2*a1) % 3
                    colour_v = (b0 + 2*b1) % 3
                    if colour_u != colour_v:
                        patterns_diff.append((a0, a1, b0, b1))

    def apply_edge(u: int, v: int, target: int) -> None:
        """Flip |target> to |1> iff the two vertices have different colours."""
        qubits = [
            problem_qubits[2*u], problem_qubits[2*u+1],
            problem_qubits[2*v], problem_qubits[2*v+1]
        ]
        for pat in patterns_diff:
            # Invert qubits that need to be |0> for the control pattern
            for i, q in enumerate(qubits):
                if pat[i] == 0:
                    qc.x(q)
            # Multi‑controlled X for this pattern (no extra ancillas)
            qc.mcx(qubits, target, mode='noancilla')
            # Restore qubits
            for i, q in enumerate(qubits):
                if pat[i] == 0:
                    qc.x(q)

    # 1. Compute each edge condition into the first four ancilla qubits.
    global_anc = ancilla_qubits[0]
    for idx, (u, v) in enumerate(edges):
        apply_edge(u, v, ancilla_qubits[idx + 1])

    # 2. Compute global AND of all four edge conditions into the global ancilla.
    edge_ancillas = ancilla_qubits[1:5]
    qc.mcx(edge_ancillas, global_anc, mode='noancilla')

    # 3. Apply phase flip on the global ancilla → -1 iff all edges are valid.
    qc.z(global_anc)

    # 4. Uncompute the global AND.
    qc.mcx(edge_ancillas, global_anc, mode='noancilla')

    # 5. Uncompute each edge condition in reverse order.
    for idx, (u, v) in reversed(list(enumerate(edges))):
        apply_edge(u, v, ancilla_qubits[idx + 1])
