from qiskit import QuantumCircuit

def build_oracle(qc: QuantumCircuit, problem_qubits: list[int],
                 ancilla_qubits: list[int]) -> None:
    """
    Grover phase oracle for subset sum: mark states where sum of selected
    elements (6,10,8,3) equals 14.
    """
    # constants
    a = [6, 10, 8, 3]
    target = 14
    n = len(ancilla_qubits)  # 5

    # helper: Quantum Fourier Transform (QFT) and its inverse
    def qft(qubits, inverse=False):
        m = len(qubits)
        if not inverse:
            # forward QFT
            for j in range(m):
                qc.h(qubits[j])
                for k in range(j + 1, m):
                    angle = math.pi / (2 ** (k - j))
                    qc.cp(angle, qubits[k], qubits[j])
            # reverse qubits
            for i in range(m // 2):
                qc.swap(qubits[i], qubits[m - 1 - i])
        else:
            # inverse QFT
            for i in range(m // 2):
                qc.swap(qubits[i], qubits[m - 1 - i])
            for j in reversed(range(m)):
                for k in reversed(range(j + 1, m)):
                    angle = -math.pi / (2 ** (k - j))
                    qc.cp(angle, qubits[k], qubits[j])
                qc.h(qubits[j])

    # --- compute sum into ancilla register ---
    qft(ancilla_qubits, inverse=False)
    for i, pqubit in enumerate(problem_qubits):
        for j, aqubit in enumerate(ancilla_qubits):
            angle = 2 * math.pi * a[i] * (2 ** j) / (2 ** n)
            # skip if angle is effectively 0 modulo 2π
            if abs(angle % (2 * math.pi)) > 1e-12:
                qc.cp(angle, pqubit, aqubit)
    qft(ancilla_qubits, inverse=True)

    # --- phase flip when sum == target ---
    bits = [(target >> k) & 1 for k in range(n)]  # LSB first
    # choose target qubit for multi-controlled Z (the LSB)
    target_qubit = ancilla_qubits[0]
    controls = ancilla_qubits[1:]  # the other 4 ancillas
    # map the target pattern to all-ones
    for k, qubit in enumerate(ancilla_qubits):
        if bits[k] == 0:
            qc.x(qubit)
    # multi-controlled phase π (Z on target when all controls are 1)
    qc.mcp(math.pi, controls, target_qubit)
    # undo X gates
    for k, qubit in enumerate(ancilla_qubits):
        if bits[k] == 0:
            qc.x(qubit)

    # --- uncompute sum (return ancilla to |0>) ---
    qft(ancilla_qubits, inverse=False)
    for i, pqubit in enumerate(problem_qubits):
        for j, aqubit in enumerate(ancilla_qubits):
            angle = 2 * math.pi * a[i] * (2 ** j) / (2 ** n)
            if abs(angle % (2 * math.pi)) > 1e-12:
                qc.cp(-angle, pqubit, aqubit)
    qft(ancilla_qubits, inverse=True)

from qiskit import QuantumCircuit

def build_oracle(qc: QuantumCircuit, problem_qubits: list[int],
                 ancilla_qubits: list[int]) -> None:
    # Constants for the subset sum problem
    a = [6, 5, 12, 6, 6]
    target = 24
    n_anc = len(ancilla_qubits)  # should be 6

    # Helper function to apply a controlled increment by 2^j
    # (adds 1 to the subregister consisting of bits j..n_anc-1)
    def apply_increment(ctrl, j, forward=True):
        indices = range(j, n_anc) if forward else range(n_anc-1, j-1, -1)
        for i in indices:
            controls = [ctrl] + ancilla_qubits[j:i]   # ancillas j..i-1
            target = ancilla_qubits[i]
            qc.mcx(controls, target)

    # ---- 1. Compute the sum into the ancilla register ----
    for i in range(len(a)):
        ctrl = problem_qubits[i]
        const = a[i]
        for j in range(n_anc):
            if (const >> j) & 1:
                apply_increment(ctrl, j, forward=True)

    # ---- 2. Apply phase oracle: -1 iff ancilla register equals target ----
    target_bits = [(target >> j) & 1 for j in range(n_anc)]
    # Flip qubits where target bit is 0
    for j in range(n_anc):
        if target_bits[j] == 0:
            qc.x(ancilla_qubits[j])

    # Multi‑controlled Z using one ancilla as target (borrowed qubit)
    qc.h(ancilla_qubits[0])
    qc.mcx(ancilla_qubits[1:], ancilla_qubits[0])
    qc.h(ancilla_qubits[0])

    # Undo the bit flips
    for j in range(n_anc-1, -1, -1):
        if target_bits[j] == 0:
            qc.x(ancilla_qubits[j])

    # ---- 3. Uncompute the sum (reverse order of increments) ----
    for i in range(len(a)-1, -1, -1):
        ctrl = problem_qubits[i]
        const = a[i]
        for j in range(n_anc-1, -1, -1):
            if (const >> j) & 1:
                apply_increment(ctrl, j, forward=False)

def build_oracle(qc, problem_qubits, ancilla_qubits):
    # Pattern: "0011" (no wildcards)
    pattern = [0, 0, 1, 1]
    n_offsets = 5  # indices 0..4

    # --- Compute match flags for each offset ---
    for offset in range(n_offsets):
        # problem qubit indices for this offset
        idxs = [problem_qubits[offset + i] for i in range(4)]

        # Flip problem qubits that should be 0 (so we control on |1>)
        for i, bit in enumerate(pattern):
            if bit == 0:
                qc.x(idxs[i])

        # Set ancilla[offset] to 1 iff all four (flipped) controls are 1
        qc.mcx(idxs, ancilla_qubits[offset])

        # Restore the problem qubits
        for i, bit in enumerate(pattern):
            if bit == 0:
                qc.x(idxs[i])

    # --- Compute the OR of all match flags ---
    or_anc = ancilla_qubits[5]
    match_ancs = ancilla_qubits[:5]  # the five match ancillas

    # De Morgan: OR = NOT(AND(NOT a_i))
    for a in match_ancs:
        qc.x(a)                     # NOT each match ancilla
    qc.mcx(match_ancs, or_anc)      # AND of the flipped bits
    qc.x(or_anc)                    # flip to obtain OR

    # Apply phase: -1 iff OR = 1
    qc.z(or_anc)

    # Uncompute the OR (inverse of above)
    qc.x(or_anc)
    qc.mcx(match_ancs, or_anc)
    for a in match_ancs:
        qc.x(a)

    # --- Uncompute each match flag ---
